```t
t 1
gate loops
task sum_series(n: int) returns (r: int)
  requires n >= 0
  ensures r == sum_series_spec(n)
spec fun sum_series_spec(k: int): int
  decreases k
= if k <= 0 then 0 else k + sum_series_spec(k - 2)
{
  r := 0;
  var i: int := n;
  while i > 0
    invariant r == sum_series_spec(n) - sum_series_spec(i)
    invariant i >= 0
    decreases i
  {
    r := r + i;
    i := i - 2;
  }
}
